mapper.select:
select
SUM(AMOUNT)
from PTL_CASH_POSITION_FLOW
where CDATE <= #{cdate,jdbcType=DATE}
and HODING_TYPE in ('01' ,'03')

    and PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}


    and ACCT_ID = #{acctId, jdbcType=VARCHAR}


    and CCY = #{ccy,jdbcType=VARCHAR}


    and ACCT_ID in (
    SELECT ACCT_NO from PTL_CAPACCT_INFO where PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
    #{item}
    )

SELECT NVL(TDY_INTINCEXP, 0) as carryOverQty
from (SELECT psv.TDY_INTINCEXP
      FROM PTL_SEC_VALUTION psv
      WHERE psv.CDATE <= to_date(#{tradeDate}, 'yyyy-MM-dd')
        AND psv.INV_AIM = '999999'
        AND psv.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
        AND psv.FINPROD_ID = #{finprodIdOrg,jdbcType=VARCHAR}
      order by psv.CDATE desc
 )
where rownum = 1

    	SELECT sum(amount)
		FROM PTL_CASH_POSITION_RULE pcpr
		WHERE pcpr.DATE_TYPE = 0
		  AND pcpr.HODING_TYPE IN ('C_11', 'C_12')
		  AND pcpr.CDATE = #{vdate,jdbcType=DATE}

            AND pcpr.PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}


            AND pcpr.ACCT_ID = #{acctNo, jdbcType=VARCHAR}
